      this.$('#relation-kind').addEventListener('change', () => { this.relationKind = this.$('#relation-kind').value; this.loadGraph(); }); this.$('#relation-direction').addEventListener('change', () => { this.direction = this.$('#relation-direction').value; this.loadGraph(); });
      const graphElement = this.$('.graph-wrap'); if (graphElement) { const svg = graphElement.querySelector('svg'); svg.style.width = Math.max(graphElement.clientWidth, Number(svg.getAttribute('width'))) + 'px'; graphElement.addEventListener('click', e => { const g = e.target.closest('[data-node-id]'); if (g) this.selectGraphNode(g.dataset.nodeId); }); graphElement.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { const g = e.target.closest('[data-node-id]'); if (g) { e.preventDefault(); this.selectGraphNode(g.dataset.nodeId); } } }); }
